// spec: specs/date-now.md 3.2–3.3 · кейс .qa/tests/date-now/DN-09.md
// Шит «דייט עכשיו» только открывается, чип выбирается без «להפעיל» — данные не меняются.
import { test, expect, type Page } from '@playwright/test';
import path from 'path';
import { saveSession } from '../_shared/session';

const CHIPS = [/^30 דק׳$/, /^שעה$/, /^שעתיים$/, /^3 שעות$/];

// Внутренний отступ (padding + рамка) по горизонтали, расстояние между соседними чипами, место значка относительно текста.
async function chipMetrics(page: Page) {
  const out: { pad: number; left: number; right: number; iconRightOfText: boolean | null }[] = [];
  for (const name of CHIPS) {
    const chip = page.getByRole('button', { name });
    await expect(chip).toBeVisible();
    out.push(
      await chip.evaluate((b) => {
        const cs = getComputedStyle(b);
        const r = b.getBoundingClientRect();
        const kids = [...b.children].map((c) => ({ txt: c.textContent?.trim() ?? '', r: c.getBoundingClientRect() }));
        const icon = kids.find((k) => k.txt === '' && k.r.width > 0);
        const text = kids.find((k) => k.txt !== '');
        return {
          pad: parseFloat(cs.paddingRight) + parseFloat(cs.borderRightWidth),
          left: r.left,
          right: r.right,
          iconRightOfText: icon && text ? icon.r.left >= text.r.right - 1 : null,
        };
      }),
    );
  }
  const sorted = [...out].sort((a, b) => a.left - b.left);
  const gaps = sorted.slice(1).map((c, i) => Math.round(c.left - sorted[i].right));
  return { chips: out, gaps };
}

async function openSheet(page: Page) {
  await page.goto('/map');
  const pill = page.getByTestId('date-now-pill');
  await expect(pill).toBeVisible({ timeout: 30_000 });
  await pill.click();
  await expect(page.getByText('פנוי/ה לדייט עכשיו?')).toBeVisible();
}

test.describe('דייט עכשיו — чипы длительности', () => {
  test.describe('бесплатный', () => {
    test.use({ storageState: path.resolve(__dirname, '../../../auth/free.json'), geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 }, permissions: ['geolocation'] });
    test.afterEach(async ({ page }) => saveSession(page, 'free'));
    test('free: чипы с отступом 12 и шагом 4, замок справа у «שעתיים»/«3 שעות» (869-7597) @iphone @prod-safe (#a5ce54)', async ({ page }) => {
      await openSheet(page);
      const m = await chipMetrics(page);
      for (const c of m.chips) expect(c.pad, 'внутренний отступ чипа free').toBeCloseTo(12, 0);
      for (const g of m.gaps) expect(g, 'шаг между чипами free').toBe(4);
      // Замок — справа от текста (RTL: значок перед текстом) у «שעתיים» и «3 שעות» (Р3).
      expect(m.chips[2].iconRightOfText).toBe(true);
      expect(m.chips[3].iconRightOfText).toBe(true);
      await page.getByRole('button', { name: 'לא עכשיו' }).click();
    });
  });

  test.describe('Premium', () => {
    test.use({ storageState: path.resolve(__dirname, '../../../auth/user2.json'), geolocation: { latitude: 32.084, longitude: 34.7832, accuracy: 10 }, permissions: ['geolocation'] });
    test.afterEach(async ({ page }) => saveSession(page, 'user2'));
    test('Premium: чипы с отступом 16 и шагом 8, у выбранного «שעתיים» ✓ справа, без замка и попапа (869-7494) @iphone @prod-safe (#a5ce54)', async ({ page }) => {
      const setDateNow: string[] = [];
      page.on('request', (r) => { if (r.url().includes('/rpc/set_date_now')) setDateNow.push(r.url()); });
      await openSheet(page);
      await page.getByRole('button', { name: CHIPS[2] }).click();
      await expect(page.getByRole('button', { name: 'לשדרג ל-Premium' })).toHaveCount(0);
      const m = await chipMetrics(page);
      for (const c of m.chips) expect(c.pad, 'внутренний отступ чипа Premium').toBeCloseTo(16, 0);
      for (const g of m.gaps) expect(g, 'шаг между чипами Premium').toBe(8);
      expect(m.chips[2].iconRightOfText, '✓ справа у выбранного').toBe(true);
      await page.getByRole('button', { name: 'לא עכשיו' }).click();
      expect(setDateNow).toHaveLength(0);
    });
  });
});
